Tính diện tích hình sau biết ${A B }=5cm$, ${C B }=12cm$, ${A D }=11cm$, ${C D }=7cm$
}{
\begin{tikzpicture}
    % Định nghĩa tọa độ của các điểm A và C (đường kính)
    \coordinate (A) at (0,0);
    \coordinate (C) at (6,0);
    \coordinate (B) at (1,2.236);  % Điểm B nằm trên đường tròn
    \coordinate (D) at (4,-2.828); % Điểm D nằm trên đường tròn

    \draw[blue, thick] (A) -- (B) -- (C) -- (D) -- cycle;

    \def\khvuong[size=#1](#2,#3,#4){%
        \draw ($(#3)!#1!(#2)$) --
        ($($(#3)!#1!(#2)$)+($(#3)!#1!(#4)$)-(#3)$)--
        ($(#3)!#1!(#4)$);
    }
    \khvuong[size=7pt](C,B,A);
        \khvuong[size=7pt](C,D,A);
    \filldraw[black] (A) circle (2pt) node[below left] {$A $};
    \filldraw[black] (B) circle (2pt) node[above left] {$B $};
    \filldraw[black] (C) circle (2pt) node[below right] {$C $};
    \filldraw[black] (D) circle (2pt) node[below right] {$D $};
\end{tikzpicture}
}
\loigiai{
Diện tích tam giác ${A B C }$ bằng $\dfrac{1}{2}A B .B C =\dfrac{1}{2}5.12=30cm^{2}$\\
Diện tích tam giác ${A D C }$ bằng $\dfrac{1}{2}A D .D C =\dfrac{1}{2}11.7=\dfrac{77}{2}cm^{2}$\\
