Tính diện tích hình sau biết ${EF}=6cm$, ${GF}=14cm$, ${EH}=13cm$, ${GH}=8cm$
}{
\begin{tikzpicture}
    % Định nghĩa tọa độ của các điểm A và C (đường kính)
    \coordinate (A) at (0,0);
    \coordinate (C) at (6,0);
    \coordinate (B) at (1,2.236);  % Điểm B nằm trên đường tròn
    \coordinate (D) at (4,-2.828); % Điểm D nằm trên đường tròn

    \draw[blue, thick] (A) -- (B) -- (C) -- (D) -- cycle;

    \def\khvuong[size=#1](#2,#3,#4){%
        \draw ($(#3)!#1!(#2)$) --
        ($($(#3)!#1!(#2)$)+($(#3)!#1!(#4)$)-(#3)$)--
        ($(#3)!#1!(#4)$);
    }
    \khvuong[size=7pt](C,B,A);
        \khvuong[size=7pt](C,D,A);
    \filldraw[black] (A) circle (2pt) node[below left] {$E$};
    \filldraw[black] (B) circle (2pt) node[above left] {$F$};
    \filldraw[black] (C) circle (2pt) node[below right] {$G$};
    \filldraw[black] (D) circle (2pt) node[below right] {$H$};
\end{tikzpicture}
}
\loigiai{
Diện tích tam giác ${EFG}$ bằng $\dfrac{1}{2}EF.FG=\dfrac{1}{2}6.14=42cm^{2}$\\
Diện tích tam giác ${EHG}$ bằng $\dfrac{1}{2}EH.HG=\dfrac{1}{2}13.8=52cm^{2}$\\
Diện tích của hình là $42cm^{2}+ 52cm^{2}=94cm^{2}$
}\end{ex}

